            if done and step_index != len(episode) - 1:
                raise ValueError(
                    f"{where} done may be True only at the last step"
                )
            prev_next = (next_r, next_c)

    out = {
        "q": [
            [state[0], state[1], action, q[(state, action)]]
            for state in states
            for action in actions
        ],
        "episodes": episodes,
    }
    return (
